  "ManagementTable": "import { useCallback, useRef, useState } from 'react';\nimport * as U from '@fiveplusone/ui';\nimport '@fiveplusone/ui/styles.css';\n\n\n\nexport function Example(){\nconst notify=(message:string)=>console.info(message);\n\nreturn ((\r\n      <U.ManagementTable\r\n        title=\"笔记本管理\"\r\n        items={[\r\n          { id: \"1\", name: \"线性代数\", members: 3 },\r\n          { id: \"2\", name: \"概率论\", members: 2 },\r\n        ]}\r\n        columns={[\r\n          { id: \"name\", label: \"名称\", render: (i) => i.name },\r\n          { id: \"members\", label: \"成员\", render: (i) => `${i.members} 人` },\r\n        ]}\r\n        actions={[\r\n          { id: \"manage\", label: \"管理\", run: (i) => notify(`管理${i.name}`) },\r\n        ]}\r\n      />\r\n    ));\n}\n",
