  "SettingsForm": "import { useCallback, useRef, useState } from 'react';\nimport * as U from '@fiveplusone/ui';\nimport '@fiveplusone/ui/styles.css';\n\n\n\nexport function Example(){\nconst notify=(message:string)=>console.info(message);\nconst [setting, setSetting] = useState(\"课栈笔记\");\nconst [enabled, setEnabled] = useState(true);\nconst done = () => notify(\"已保存\");\nreturn ((\r\n      <U.SettingsForm\r\n        title=\"笔记本设置\"\r\n        fields={[\r\n          {\r\n            id: \"name\",\r\n            label: \"名称\",\r\n            value: setting,\r\n            description: \"方便自己和同学找到。\",\r\n          },\r\n          {\r\n            id: \"view\",\r\n            label: \"打开方式\",\r\n            value: enabled ? \"reading\" : \"outline\",\r\n            options: [\r\n              { value: \"reading\", label: \"继续阅读\" },\r\n              { value: \"outline\", label: \"先查看目录\" },\r\n            ],\r\n            description: \"选择打开笔记本后先看到的内容。\",\r\n          },\r\n        ]}\r\n        onChange={(id, value) => id === \"name\" ? setSetting(value) : setEnabled(value === \"reading\")}\r\n        onSave={done}\r\n      />\r\n    ));\n}\n",
